#!/usr/bin/env python3
# 116_remap_broll_timestamps.py
# v1.1 (2025-08-28)
# - MODIFIED: Script now takes a single '--project-root' argument and automatically
#             locates the necessary 'timecode_map.json' and 'placeholder_index.json'
#             files, making it suitable for automated pipeline execution.
#
# Purpose: Remaps B-roll placeholder timestamps from the original source media's
# continuous timeline to the new, discontinuous "clean takes" timeline.
#
# How it works:
# 1. Reads a 'timecode_map.json' file generated by 115_timeline_builder.py.
#    This map contains segments defining how source time maps to the new timeline.
# 2. Reads the 'placeholder_index.json' which contains B-roll timestamps
#    relative to the original, uncut source media.
# 3. Creates a timestamped backup of the original placeholder_index.json.
# 4. For each B-roll item, it finds the corresponding segment in the timecode map
#    and calculates the new, correct start time for the clean timeline.
# 5. Overwrites the original 'placeholder_index.json' with the remapped data,
#    allowing the next script (118) to use it without modification.

import json
import shutil
import argparse
from pathlib import Path
from datetime import datetime
from typing import List, Dict, Any, Optional

def find_segment_for_time(time_map: List[Dict[str, float]], source_time: float) -> Optional[Dict[str, float]]:
    """Finds the time map segment that contains the given source time."""
    for segment in time_map:
        # Using a small tolerance for floating point comparisons at the edges
        if segment['source_start'] - 0.01 <= source_time <= segment['source_end'] + 0.01:
            return segment
    return None

def remap_timestamps(map_path: Path, placeholder_path: Path):
    """
    Remaps timestamps in placeholder_index.json using the timecode_map.json.
    """
    if not map_path.exists():
        raise FileNotFoundError(f"Timecode map not found at: {map_path}")
    if not placeholder_path.exists():
        raise FileNotFoundError(f"B-roll placeholder index not found at: {placeholder_path}")

    print(f"-> Loading timecode map from: {map_path}")
    with open(map_path, 'r', encoding='utf-8') as f:
        time_map = json.load(f)

    print(f"-> Loading B-roll placeholders from: {placeholder_path}")
    with open(placeholder_path, 'r', encoding='utf-8') as f:
        placeholder_data = json.load(f)

    # Create a backup of the original placeholder file
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_path = placeholder_path.parent / f"{placeholder_path.stem}_backup_{timestamp}.json"
    shutil.copy(placeholder_path, backup_path)
    print(f"-> Created backup of original placeholders at: {backup_path}")

    remapped_count = 0
    unmapped_count = 0

    for item in placeholder_data.get("placeholders", []):
        source_start_time = item.get("start")
        if source_start_time is None:
            continue

        segment = find_segment_for_time(time_map, source_start_time)

        if segment:
            # Formula: new_start = timeline_start_of_segment + (broll_time - source_start_of_segment)
            time_in_segment = source_start_time - segment['source_start']
            new_start_time = segment['timeline_start'] + time_in_segment
            
            print(f"   - Remapping '{Path(item['file']).name}':")
            print(f"     Original Start: {source_start_time:.2f}s")
            print(f"     New Start: {new_start_time:.2f}s")
            
            item['start'] = new_start_time
            remapped_count += 1
        else:
            print(f"   - WARNING: Could not find a map segment for B-roll at {source_start_time:.2f}s. Skipping.")
            unmapped_count += 1
    
    # Overwrite the original file with the remapped data
    with open(placeholder_path, 'w', encoding='utf-8') as f:
        json.dump(placeholder_data, f, indent=2)
    
    print("\n-> Remapping complete.")
    print(f"   {remapped_count} items remapped successfully.")
    if unmapped_count > 0:
        print(f"   {unmapped_count} items could not be mapped and were left unchanged.")
    print(f"-> Overwrote '{placeholder_path}' with remapped timestamps.")


def main():
    parser = argparse.ArgumentParser(
        description="Remap B-roll timestamps from source media time to clean timeline time.",
        formatter_class=argparse.RawTextHelpFormatter
    )
    parser.add_argument(
        '--project-root',
        required=True,
        help="Path to the root directory of the project."
    )
    args = parser.parse_args()

    project_root = Path(args.project_root)
    
    # Automatically locate the required files based on the project structure
    map_path = project_root / "timecode_map.json"
    placeholder_path = project_root / "ai_working_files" / "46_ai_b_roll_plans" / "placeholder_index.json"

    try:
        remap_timestamps(map_path, placeholder_path)
    except (FileNotFoundError, KeyError) as e:
        print(f"\nERROR: {e}")
        exit(1)

if __name__ == "__main__":
    main()
